  ('db-kickback', 1, 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.'),
  ('db-kickback', 2, 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.'),
  ('db-kickback', 3, 'Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados.'),
  ('db-kickback', 4, 'Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.'),
  ('db-kickback', 5, 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.'),
  ('db-kickback', 6, 'Repite el número de repeticiones deseado.'),
  ('cable-kickback', 1, 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.'),
  ('cable-kickback', 2, 'Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.'),
  ('cable-kickback', 3, 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.'),
  ('cable-kickback', 4, 'Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.'),
  ('cable-kickback', 5, 'Extiende el antebrazo hacia atrás, enderezando el brazo por completo.'),
  ('cable-kickback', 6, 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.'),
  ('cable-kickback', 7, 'Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('machine-triceps-extension', 1, 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.'),
  ('machine-triceps-extension', 2, 'Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti.'),
  ('machine-triceps-extension', 3, 'Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos.'),
  ('machine-triceps-extension', 4, 'Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos.'),
  ('machine-triceps-extension', 5, 'Repite el número de repeticiones deseado.'),
  ('machine-dip', 1, 'Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados.'),
  ('machine-dip', 2, 'Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos.'),
  ('machine-dip', 3, 'Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo.'),
  ('machine-dip', 4, 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.'),
  ('machine-dip', 5, 'Repite el número de repeticiones deseado.'),
  ('triceps-dip', 1, 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.'),
  ('triceps-dip', 2, 'Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.'),
  ('triceps-dip', 3, 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.'),
  ('triceps-dip', 4, 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.'),
  ('triceps-dip', 5, 'Repite el número de repeticiones deseado.'),
  ('bench-dip', 1, 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.'),
  ('bench-dip', 2, 'Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo.'),
  ('bench-dip', 3, 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.'),
  ('bench-dip', 4, 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.'),
  ('bench-dip', 5, 'Repite el número de repeticiones deseado.'),
  ('diamond-push-up', 1, 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.'),
  ('diamond-push-up', 2, 'Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.'),
  ('diamond-push-up', 3, 'Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.'),
  ('diamond-push-up', 4, 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.'),
  ('diamond-push-up', 5, 'Repite el número de repeticiones deseado.'),
  ('wrist-curl', 1, 'Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.'),
  ('wrist-curl', 2, 'Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.'),
  ('wrist-curl', 3, 'Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.'),
  ('wrist-curl', 4, 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.'),
  ('wrist-curl', 5, 'Repite el número de repeticiones deseado.'),
  ('reverse-wrist-curl', 1, 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo.'),
  ('reverse-wrist-curl', 2, 'Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.'),
  ('reverse-wrist-curl', 3, 'Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.'),
  ('reverse-wrist-curl', 4, 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.'),
  ('reverse-wrist-curl', 5, 'Repite el número de repeticiones deseado.'),
  ('reverse-crunch', 1, 'Túmbate boca arriba con los brazos extendidos a los lados del cuerpo.'),
  ('reverse-crunch', 2, 'Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo.'),
  ('reverse-crunch', 3, 'Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho.'),
  ('reverse-crunch', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.'),
  ('reverse-crunch', 5, 'Repite el número de repeticiones deseado.'),
  ('decline-crunch', 1, 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados.'),
  ('decline-crunch', 2, 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.'),
  ('decline-crunch', 3, 'Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso.'),
  ('decline-crunch', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.'),
  ('decline-crunch', 5, 'Repite el número de repeticiones deseado.'),
  ('oblique-crunch', 1, 'Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.'),
  ('oblique-crunch', 2, 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.'),
  ('oblique-crunch', 3, 'Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.'),
  ('oblique-crunch', 4, 'Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.'),
  ('oblique-crunch', 5, 'Repite hacia el otro lado, alternando los lados en cada repetición.'),
  ('cross-body-crunch', 1, 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.'),
  ('cross-body-crunch', 2, 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.'),
  ('cross-body-crunch', 3, 'Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.'),
  ('cross-body-crunch', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.'),
  ('cross-body-crunch', 5, 'Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.'),
  ('cross-body-crunch', 6, 'Repite el número de repeticiones deseado.'),
  ('air-bike', 1, 'Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.'),
  ('air-bike', 2, 'Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.'),
  ('air-bike', 3, 'Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.'),
  ('air-bike', 4, 'Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.'),
  ('air-bike', 5, 'Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.'),
  ('sit-up', 1, 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.'),
  ('sit-up', 2, 'Cruza los brazos sobre el pecho.'),
  ('sit-up', 3, 'Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas.'),
  ('sit-up', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.'),
  ('sit-up', 5, 'Repite el número de repeticiones deseado.'),
  ('decline-sit-up', 1, 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.'),
  ('decline-sit-up', 2, 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.'),
  ('decline-sit-up', 3, 'Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas.'),
  ('decline-sit-up', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.'),
  ('decline-sit-up', 5, 'Repite el número de repeticiones deseado.'),
  ('jackknife-sit-up', 1, 'Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza.'),
  ('jackknife-sit-up', 2, 'Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies.'),
  ('jackknife-sit-up', 3, 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.'),
  ('jackknife-sit-up', 4, 'Repite el número de repeticiones deseado.'),
  ('lying-leg-raise', 1, 'Túmbate en un banco plano con la espalda presionada contra él.'),
  ('lying-leg-raise', 2, 'Coloca las manos debajo de los glúteos como apoyo.'),
  ('lying-leg-raise', 3, 'Mantén las piernas rectas y juntas, y elévalas hacia el techo.'),
  ('lying-leg-raise', 4, 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.'),
  ('lying-leg-raise', 5, 'Repite el número de repeticiones deseado.'),
  ('captains-chair-leg-raise', 1, 'Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas.'),
  ('captains-chair-leg-raise', 2, 'Mantén la parte superior del cuerpo estable y la espalda recta.'),
  ('captains-chair-leg-raise', 3, 'Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.'),
  ('captains-chair-leg-raise', 4, 'Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.'),
  ('captains-chair-leg-raise', 5, 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.'),
  ('captains-chair-leg-raise', 6, 'Repite el número de repeticiones deseado.'),
  ('hanging-oblique-knee-raise', 1, 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.'),
  ('hanging-oblique-knee-raise', 2, 'Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces.'),
  ('hanging-oblique-knee-raise', 3, 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.'),
  ('hanging-oblique-knee-raise', 4, 'Repite hacia el otro lado, girando el torso en la dirección opuesta.'),
  ('hanging-oblique-knee-raise', 5, 'Continúa alternando lados durante el número de repeticiones deseado.'),
  ('russian-twist', 1, 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.'),
  ('russian-twist', 2, 'Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.'),
  ('russian-twist', 3, 'Junta las manos frente al pecho o sujeta una pesa si lo deseas.'),
  ('russian-twist', 4, 'Levanta los pies del suelo, equilibrándote sobre los isquiones.'),
  ('russian-twist', 5, 'Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo.'),
  ('russian-twist', 6, 'Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo.'),
  ('russian-twist', 7, 'Continúa alternando lados durante el número de repeticiones deseado.'),
  ('ab-wheel', 1, 'Arrodíllate en el suelo y coloca el rodillo frente a ti.'),
  ('ab-wheel', 2, 'Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante.'),
  ('ab-wheel', 3, 'Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído.'),
  ('ab-wheel', 4, 'Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.'),
  ('ab-wheel', 5, 'Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado.'),
  ('ab-wheel', 6, 'Repite el número de repeticiones deseado.'),
  ('dead-bug', 1, 'Túmbate boca arriba con los brazos extendidos hacia el techo.'),
  ('dead-bug', 2, 'Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.'),
  ('dead-bug', 3, 'Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.'),
  ('dead-bug', 4, 'Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.'),
  ('dead-bug', 5, 'Haz una pausa breve y luego vuelve a la posición inicial.'),
  ('dead-bug', 6, 'Repite el movimiento con el brazo izquierdo y la pierna derecha.'),
  ('dead-bug', 7, 'Continúa alternando lados durante el número de repeticiones deseado.'),
  ('mountain-climber', 1, 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.'),
  ('mountain-climber', 2, 'Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho.'),
  ('mountain-climber', 3, 'Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado.'),
  ('mountain-climber', 4, 'Mantén un ritmo constante y respira de forma regular durante todo el ejercicio.'),
  ('mountain-climber', 5, 'Repite el número de repeticiones deseado.'),
  ('machine-crunch', 1, 'Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad.'),
  ('machine-crunch', 2, 'Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo.'),
  ('machine-crunch', 3, 'Sujeta las asas o las barras laterales para mayor estabilidad.'),
  ('machine-crunch', 4, 'Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo.'),
  ('machine-crunch', 5, 'Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen.'),
  ('machine-crunch', 6, 'Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba.'),
  ('machine-crunch', 7, 'Repite el número de repeticiones deseado.'),
  ('db-side-bend', 1, 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado.'),
  ('db-side-bend', 2, 'Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad.'),
  ('db-side-bend', 3, 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.'),
  ('db-side-bend', 4, 'Repite el número de repeticiones deseado, luego cambia de lado y repite.');
